<?php /* Template Name: Contact */ get_header(); $contact_status = atelier_form_status('atelier_contact'); ?><section class="editorial-heading"><p class="eyebrow">WE’RE REAL PEOPLE</p><h1>Say <em>hello.</em></h1><p>Questions about a piece, an order, or just want to share how it found a home?</p></section><section class="contact-layout"><div class="contact-details"><div><span class="eyebrow">GET IN TOUCH</span><a href="#contact-form">Use the message form ↗</a></div><div><span class="eyebrow">STUDIO HOURS</span><p>Monday–Friday<br>10 am–5 pm (local time)</p></div><div><span class="eyebrow">ORDERS</span><a href="<?php echo esc_url(wc_get_page_permalink('myaccount')); ?>">Track an order ↗</a></div></div><div class="contact-form" id="contact-form"><h2>Send a note.</h2><p>Your message is saved in this demo site’s private WordPress inbox. Please don’t include sensitive information.</p><?php if ($contact_status === 'sent'): ?><p class="form-feedback" role="status">Thanks for writing. Your note is in our inbox.</p><?php elseif ($contact_status === 'error'): ?><p class="form-feedback form-error" role="alert">Please check the required fields and try again.</p><?php endif; ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="atelier_contact"><?php wp_nonce_field('atelier_contact', 'atelier_contact_nonce'); ?><label>Your name<input type="text" name="name" autocomplete="name" maxlength="120" placeholder="Name" required></label><label>Email address<input type="email" name="email" autocomplete="email" maxlength="254" placeholder="you@example.com" required></label><label>What’s on your mind?<textarea name="message" rows="5" maxlength="5000" placeholder="Write a little note..." required></label><label class="consent-label"><input type="checkbox" name="consent" value="1" required><span>I agree to have my message stored so the Atelier team can reply.</span></label><div class="honeypot" aria-hidden="true"><label>Leave this field blank<input type="text" name="company" tabindex="-1" autocomplete="off"></label></div><button type="submit" class="button button-dark">Send message ↗</button></form></div></section><?php get_footer(); ?>
